<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\View;use App\Services\PermissionService;use App\Support\Jalali;use PDO;
final class PriceController {
 public function index():void{Auth::requireLogin();PermissionService::require(Auth::userId(),'prices.view');$q=trim((string)($_GET['q']??''));$sort=(string)($_GET['sort']??'registered_at');$dir=($_GET['direction']??'desc')==='asc'?'ASC':'DESC';$allowed=['product_code'=>'p.product_code','product_name'=>'p.product_name','unit_name'=>'u.name','registered_at'=>'p.registered_at','latest_price_date'=>'latest_price_date'];$order=$allowed[$sort]??$allowed['registered_at'];$where='';$params=[];if($q!==''){$where=' WHERE p.product_code LIKE :q OR p.product_name LIKE :q';$params['q']='%'.$q.'%';}$pdo=Database::connection();$sql="SELECT p.id,p.product_code,p.product_name,p.registered_at,u.name unit_name,(SELECT MAX(price_received_at) FROM product_prices pp WHERE pp.product_id=p.id) latest_price_date FROM products p INNER JOIN units u ON u.id=p.unit_id{$where} ORDER BY {$order} {$dir}";$s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll();$ids=array_column($products,'id');$prices=[];if($ids){$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM product_prices WHERE product_id IN ({$in}) ORDER BY product_id,source_no");$s->execute($ids);foreach($s->fetchAll() as $r)$prices[$r['product_id']][]=$r;}$data=compact('products','prices','q','sort','dir');if(isset($_GET['ajax'])){View::render('prices/table',$data);return;}View::render('prices/index',$data);}
 public function form(?int $id=null):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$id?'prices.edit':'prices.create');$pdo=Database::connection();$units=$pdo->query('SELECT id,name FROM units WHERE is_active=1 ORDER BY name')->fetchAll();$product=null;$prices=[];if($id){$s=$pdo->prepare('SELECT * FROM products WHERE id=:id');$s->execute(['id'=>$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('رکورد یافت نشد.');}$s=$pdo->prepare('SELECT * FROM product_prices WHERE product_id=:id ORDER BY source_no');$s->execute(['id'=>$id]);$prices=$s->fetchAll();}View::render($id?'prices/edit':'prices/create',compact('units','product','prices'));}
 public function save(?int $id=null):void{Auth::requireLogin();PermissionService::require(Auth::userId(),$id?'prices.edit':'prices.create');Security::verifyCsrf();$code=trim((string)($_POST['product_code']??''));$name=trim((string)($_POST['product_name']??''));$unit=(int)($_POST['unit_id']??0);$rows=$_POST['prices']??[];$valid=[];if($code===''||mb_strlen($code)>100||$name===''||mb_strlen($name)>255||$unit<1){http_response_code(422);exit('اطلاعات کالا نامعتبر است.');}if(!is_array($rows)||count($rows)>3){http_response_code(422);exit('حداکثر سه منبع مجاز است.');}foreach($rows as $row){$supplier=trim((string)($row['supplier']??''));$package=$row['package_price']??'';$unitPrice=$row['unit_price']??'';$date=trim((string)($row['price_received_at']??''));if($supplier===''&&$package===''&&$unitPrice===''&&$date==='')continue;if($supplier===''||$package===''||$unitPrice===''||$date===''){http_response_code(422);exit('هر منبع باید کامل باشد.');}if(!is_numeric($package)||!is_numeric($unitPrice)||$package<0||$unitPrice<0){http_response_code(422);exit('قیمت نامعتبر است.');}$valid[]=[$supplier,(float)$package,(float)$unitPrice,Jalali::toGregorian($date)];}if(!$valid){http_response_code(422);exit('حداقل یک قیمت کامل باید ثبت شود.');}$pdo=Database::connection();$s=$pdo->prepare('SELECT id FROM units WHERE id=:id AND is_active=1');$s->execute(['id'=>$unit]);if(!$s->fetchColumn()){http_response_code(422);exit('واحد انتخاب‌شده معتبر نیست.');}Database::transaction(function(PDO $pdo)use($id,$code,$name,$unit,$valid):void{if($id){$s=$pdo->prepare('UPDATE products SET product_code=:code,product_name=:name,unit_id=:unit,updated_at=GETDATE() WHERE id=:id');$s->execute(['code'=>$code,'name'=>$name,'unit'=>$unit,'id'=>$id]);$productId=$id;$s=$pdo->prepare('DELETE FROM product_prices WHERE product_id=:id');$s->execute(['id'=>$id]);}else{$s=$pdo->prepare('INSERT INTO products(product_code,product_name,unit_id,registered_at,created_at,updated_at) VALUES(:code,:name,:unit,GETDATE(),GETDATE(),GETDATE())');$s->execute(['code'=>$code,'name'=>$name,'unit'=>$unit]);$productId=(int)$pdo->lastInsertId();}$s=$pdo->prepare('INSERT INTO product_prices(product_id,source_no,supplier,package_price,unit_price,price_received_at,created_at,updated_at) VALUES(:pid,:no,:supplier,:package,:unit,:date,GETDATE(),GETDATE())');foreach($valid as $i=>$r)$s->execute(['pid'=>$productId,'no'=>$i+1,'supplier'=>$r[0],'package'=>$r[1],'unit'=>$r[2],'date'=>$r[3]]);});Security::redirect('/prices');}
 public function delete(int $id):void{Auth::requireLogin();PermissionService::require(Auth::userId(),'prices.delete');Security::verifyCsrf();$s=Database::connection()->prepare('DELETE FROM products WHERE id=:id');$s->execute(['id'=>$id]);Security::redirect('/prices');}
}
